PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX : <http://example.org/ontology#>

SELECT ?class ?significance
WHERE {
    ?class rdf:type owl:Class .
    OPTIONAL {
        ?class rdfs:subClassOf ?superClass .
        BIND(CONCAT("SubClass of: ", COALESCE(STR(?superClass), "None")) AS ?subSignificance)
    }
    OPTIONAL {
        ?class rdfs:seeAlso ?related .
        BIND(CONCAT("See also: ", COALESCE(STR(?related), "None")) AS ?seeAlsoSignificance)
    }
    BIND(COALESCE(?subSignificance, ?seeAlsoSignificance, "No significance") AS ?significance)
}

